// Plan the run: clean the keywords, read "your product", and decide which keyword pages need a new search.
// A keyword saved in the last 24 hours (by i1, i2, i3 or i4) is reused: no search, same page the other tools scored.
const REUSE_HOURS = 24;
const MAX_KEYWORDS = 5;
const form = $('Targeting form').first().json;
const clean = s => String(s || '').toLowerCase()
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
const marketplace = form.Marketplace || 'amazon.com';

// Keywords: one per line (commas and semicolons also split), duplicates removed, first 5 kept
const all = String(form.Keywords || '').split(/[\n,;]+/).map(clean).filter(Boolean);
const tooShort = [...new Set(all.filter(w => w.replace(/[^a-z]/g, '').length < 3))];
const unique = [...new Set(all)].filter(w => !tooShort.includes(w));
if (!unique.length) throw new Error('No keywords entered. Type 2 to 5 related keywords, one per line.');
const keywords = unique.slice(0, MAX_KEYWORDS);
const notes = [];
if (tooShort.length) notes.push(`Skipped (too short to be a product keyword): ${tooShort.join(', ')}`);
if (unique.length > MAX_KEYWORDS) notes.push(`Only the first ${MAX_KEYWORDS} keywords were used; left out: ${unique.slice(MAX_KEYWORDS).join(', ')}`);
if (keywords.length === 1) notes.push('Only 1 keyword: "ranks on how many of your keywords" cannot separate competitors. Use 2 to 5.');

// Your product (all optional). Invalid numbers are ignored and said so, never guessed.
const num = (v, lo, hi, label) => {
  const raw = String(v ?? '').trim();
  if (raw === '') return null;
  const s = raw.replace(/[^0-9.]/g, '');
  if (s === '') { notes.push(`"${label}" ignored: "${raw}" is not a number`); return null; }
  const n = Number(s);
  if (!Number.isFinite(n) || n < lo || n > hi) { notes.push(`"${label}" ignored: ${v} is not between ${lo} and ${hi}`); return null; }
  return n;
};
const you = {
  price: num(form['Your price'], 0.01, 100000, 'Your price'),
  rating: num(form['Your rating'], 1, 5, 'Your rating'),
  reviews: num(form['Your review count'], 0, 10000000, 'Your review count'),
};
// Your brand / ASINs: left out of the competitor list
const ownRaw = String(form['Your brand or ASINs'] || '').split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
const isAsin = s => /^[A-Z0-9]{10}$/i.test(s) && /\d/.test(s); // ASINs always mix letters and digits (B0…)
const own_asins = ownRaw.filter(isAsin).map(s => s.toUpperCase());
const own_brands = ownRaw.filter(s => !isAsin(s)).map(s => s.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean);

// "2026-10-16 13:21:47 UTC" -> milliseconds
const toMs = t => Date.parse(String(t).replace(' UTC', 'Z').replace(' ', 'T'));
const latest = {};
for (const r of $('Read History').all().map(i => i.json)) {
  if (!r.run_id || r.marketplace !== marketplace || !keywords.includes(r.keyword)) continue;
  const t = toMs(r.checked_at);
  if (!latest[r.keyword] || t > latest[r.keyword].t) latest[r.keyword] = { run_id: r.run_id, checked_at: r.checked_at, t };
}
const now = Date.now();
const pages = keywords.map((keyword, i) => {
  const l = latest[keyword];
  const age = l ? (now - l.t) / 3600000 : null;
  const reuse = !!l && age >= 0 && age <= REUSE_HOURS;
  return { order: i + 1, keyword, marketplace, reuse, reuse_run_id: reuse ? l.run_id : null, age_hours: age === null ? null : Math.round(age * 10) / 10 };
});
const toSearch = pages.filter(p => !p.reuse);

return [{
  json: {
    batch_id: $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT',
    marketplace,
    keywords,
    pages,
    to_search: toSearch.map(p => p.keyword),
    any_search: toSearch.length > 0,
    you,
    own_asins,
    own_brands,
    notes,
  },
}];

// One item per keyword that needs a new Amazon search (1 SerpApi search each)
const plan = $('Plan Run').first().json;
return plan.pages.filter(p => !p.reuse).map(p => ({ json: { keyword: p.keyword, marketplace: p.marketplace, order: p.order } }));

// Bundle what the core needs: fresh searches + saved runs, plus the history for the stability check.
// Search results line up with Split Searches by position (failed searches included, the core reports them).
const plan = $('Plan Run').first().json;
let fresh = [];
try {
  if ($('Search Amazon (SerpApi)').isExecuted) fresh = $('Search Amazon (SerpApi)').all().map(i => i.json);
} catch (e) {
  fresh = []; // every page was reused, the search node did not run
}
const searched = plan.pages.filter(p => !p.reuse);
const history = $('Read History').all().map(i => i.json).filter(r => r.run_id);
const searches = plan.pages.map(p => {
  const s = { order: p.order, keyword: p.keyword, marketplace: p.marketplace };
  if (p.reuse) s.listings = history.filter(r => r.run_id === p.reuse_run_id);
  else s.response = fresh[searched.indexOf(p)] ?? { error: 'no response' };
  return s;
});
return [{ json: { tool: 'i3', batch_id: plan.batch_id, searches, history, dropped: [] } }];

// Merge the keyword pages into ONE competitor list and rank it by relevance. No AI: every number comes from the pages.
// A competitor = product families (variations grouped by the core) from different keywords that are the same product:
//   they share an ASIN, or they have the same brand + same shared review count (50+) + same rating (the core's family rule).
const MAX_LISTED = 25;   // rows written to the Targets tab
const MAX_LOOKUPS = 8;   // product-page lookups (1 SerpApi search each)
const REUSE_HOURS = 24;  // a Products row this fresh is reused instead of a new lookup
const plan = $('Plan Run').first().json;
const core = $('Toolkit Core').first().json;
const details = core.details || [];
if (!details.length) throw new Error('None of the keywords could be analyzed. See the Keywords notes in the core output.');
const r1 = x => Math.round(x * 10) / 10;
const clamp = x => Math.max(0, Math.min(1, x));
const bkey = b => String(b || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const k = details.length;
const stem = w => w.replace(/(es|s)$/, '');
// Title first-words that are colours or adjectives, not brands (seen live: "Black", "Ultra", "Royal")
const NOT_BRANDS = new Set(['black', 'white', 'grey', 'gray', 'blue', 'pink', 'red', 'green', 'purple', 'beige', 'navy', 'ultra', 'royal', 'luxury', 'soft', 'memory', 'comfort', 'best', 'travel', 'portable', 'adjustable', 'deluxe', 'classic', 'organic', 'natural']);
const kwWords = new Set(plan.keywords.flatMap(kw => kw.split(' ')).map(w => stem(bkey(w))));

// ---- 1. Every family on every page, with its page's total sales ----
const nodes = [];
details.forEach((d, ki) => {
  const pageUnits = (d.families || []).reduce((s, f) => s + (f.units || 0), 0);
  for (const f of d.families || []) nodes.push({ ki, keyword: d.keyword, run_id: d.run_id, pageUnits, f, bk: bkey(f.brand) });
});

// ---- 2. Union families that are the same product across pages ----
const parent = nodes.map((_, i) => i);
const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
const join = (a, b) => { parent[find(a)] = find(b); };
const byAsin = {};
nodes.forEach((n, i) => { for (const a of n.f.asins) { if (byAsin[a] !== undefined) join(i, byAsin[a]); else byAsin[a] = i; } });
const sig = {};
nodes.forEach((n, i) => {
  if ((n.f.reviews || 0) < 50 || n.f.rating === null || !n.bk) return;
  const s = `${n.bk}|${n.f.reviews}|${n.f.rating}`;
  if (sig[s] !== undefined) join(i, sig[s]); else sig[s] = i;
});
const groups = {};
nodes.forEach((n, i) => (groups[find(i)] ??= []).push(n));

// Brands with an established (1000+ review) product on any page: their low-review listings are not newcomers
const established = new Set(nodes.filter(n => n.f.reviews >= 1000 && n.bk).map(n => n.bk));

// ---- 3. One record per competitor ----
let competitors = Object.values(groups).map(members => {
  const byKw = {};
  for (const m of members) { // a product can appear twice on one page only as two families; keep the bigger one
    const cur = byKw[m.keyword];
    if (!cur || m.f.units > cur.f.units || (m.f.units === cur.f.units && m.f.position < cur.f.position)) byKw[m.keyword] = m;
  }
  const per = Object.values(byKw);
  const lead = [...per].sort((a, b) => (b.f.units - a.f.units) || (a.f.position - b.f.position))[0];
  const mostReviews = [...per].sort((a, b) => b.f.reviews - a.f.reviews)[0];
  const asins = [...new Set(members.flatMap(m => m.f.asins))];
  const best_position = Math.min(...per.map(m => m.f.position));
  // Sales: the HIGHEST badge floor across keywords, never the sum (the same buyers show up on every page)
  const units = Math.max(...per.map(m => m.f.units || 0));
  const shares = per.map(m => (m.pageUnits ? m.f.units / m.pageUnits : 0));
  const share = Math.max(...shares);
  // A "brand" that is just a word from your keywords (e.g. "Resistance") is a title guess gone wrong: treat as unknown
  const guessed = (per.find(m => m.f.brand) || {}).f?.brand || null;
  const brand = guessed && (kwWords.has(stem(bkey(guessed))) || NOT_BRANDS.has(bkey(guessed))) ? null : guessed;
  const coverageN = per.length;
  const pCov = 50 * coverageN / k;
  const pPos = 30 * clamp(1 - (best_position - 1) / 50);
  const pShare = 20 * clamp(share / 0.2);
  const relevance = Math.round(pCov + pPos + pShare);
  return {
    competitor_asin: lead.f.best_asin,
    asins,
    family_id: lead.f.family_id,
    brand,
    brand_key: bkey(brand),
    title: lead.f.title,
    keywords_ranked_on: per.sort((a, b) => a.ki - b.ki).map(m => `${m.keyword} (#${m.f.position})`).join(' | '),
    coverage: `${coverageN} of ${k}`,
    coverage_n: coverageN,
    best_position,
    lead_keyword: lead.keyword,
    lead_run_id: lead.run_id,
    has_sales: per.some(m => m.f.has_sales),
    units_floor: units,
    page_sales_share_pct: r1(share * 100),
    price: lead.f.price,
    rating: mostReviews.f.rating,
    reviews: mostReviews.f.reviews,
    family_size: lead.f.asins.length,
    newcomer: mostReviews.f.reviews < 1000 && !established.has(bkey(brand)),
    relevance,
    relevance_breakdown: `keywords ${coverageN}/${k} → ${r1(pCov)}/50 + best position #${best_position} → ${r1(pPos)}/30 + page sales share ${r1(share * 100)}% → ${r1(pShare)}/20 (full at 20%)`,
  };
});

// ---- 4. Leave out your own products ----
// Exact brand match only: "Napfun Pro" must not hide "Napfun"
const isOwn = c => c.asins.some(a => plan.own_asins.includes(a))
  || (c.brand_key && plan.own_brands.includes(c.brand_key));
const ownCount = competitors.filter(isOwn).length;
competitors = competitors.filter(c => !isOwn(c));

// Fixed order: relevance, then sales, then reviews, then position (same data always gives the same list)
competitors.sort((a, b) => (b.relevance - a.relevance) || (b.units_floor - a.units_floor) || (b.reviews - a.reviews) || (a.best_position - b.best_position));

// ---- 5. Market medians: the comparison point when you did not enter your own product ----
const median = arr => {
  const v = arr.filter(x => typeof x === 'number' && Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
};
const selling = competitors.filter(c => c.units_floor > 0);
const base = selling.length >= 5 ? selling : competitors;
const market = {
  price: median(base.map(c => c.price)) === null ? null : Math.round(median(base.map(c => c.price)) * 100) / 100,
  rating: median(base.map(c => c.rating)),
  reviews: median(base.map(c => c.reviews)),
  based_on: `${base.length} ${base === selling ? 'selling ' : ''}competitors`,
};

// ---- 6. Which products get a product-page lookup (BSR, seller, real brand, 1-2 star share) ----
const listed = competitors.slice(0, MAX_LISTED).map((c, i) => ({ ...c, rank: i + 1 }));
const toMs = t => Date.parse(String(t).replace(' UTC', 'Z').replace(' ', 'T'));
const runTime = runId => toMs(String(runId || '').split('|').pop());
const now = Date.now();
const saved = $('Read Products').all().map(i => i.json)
  .filter(p => p.asin && p.lookup_status === 'ok' && p.marketplace === plan.marketplace)
  .map(p => ({ ...p, age_hours: (now - runTime(p.run_id)) / 3600000 }))
  .filter(p => Number.isFinite(p.age_hours) && p.age_hours >= 0 && p.age_hours <= REUSE_HOURS)
  .sort((a, b) => a.age_hours - b.age_hours);
const reused = {};
const lookups = [];
for (const c of listed.slice(0, MAX_LOOKUPS)) {
  const hit = saved.find(p => c.asins.includes(p.asin));
  if (hit) { reused[c.competitor_asin] = hit; continue; }
  lookups.push({
    role: `i3 target #${c.rank}`, asin: c.competitor_asin, family_id: c.family_id, family_size: c.family_size,
    brand_guess: c.brand ?? '', title: c.title, price: c.price, rating: c.rating, reviews: c.reviews,
    units_family: c.units_floor, keyword: c.lead_keyword, marketplace: plan.marketplace, run_id: c.lead_run_id,
  });
}

// ---- 7. Keyword ideas from Amazon's own suggestions (saved by every search, so 0 extra searches) ----
const latestKw = {};
const kwRows = [...$('Read Keywords').all().map(i => i.json), ...(core.keywords || [])]
  .filter(r => r.status === 'ok' && r.marketplace === plan.marketplace && plan.keywords.includes(r.keyword));
for (const r of kwRows) if (!latestKw[r.keyword] || String(r.checked_at) > String(latestKw[r.keyword].checked_at)) latestKw[r.keyword] = r;
// Head word = the product noun: last word before "for/with/..." ("neck pillow for travel" -> pillow, not travel)
const headOf = kw => kw.split(/ (?:for|with|without|in|on|to|of|and) /)[0].split(' ').pop();
const heads = new Set(plan.keywords.map(kw => stem(headOf(kw))));
const suggestions = new Set();
for (const r of Object.values(latestKw)) for (const s of String(r.related_searches || '').split(' | ')) {
  const t = s.toLowerCase().trim();
  if (t && !plan.keywords.includes(t)) suggestions.add(t);
}
const related = [], complements = [];
for (const s of suggestions) (s.split(' ').some(w => heads.has(stem(w))) ? related : complements).push(s);

// Keywords that could not be analyzed
const failed = (core.keywords || []).filter(r => r.status !== 'ok' && plan.keywords.includes(r.keyword)).map(r => `${r.keyword} (${r.status}: ${r.note || ''})`);

return [{
  json: {
    listed,
    competitors_found: competitors.length + ownCount,
    own_excluded: ownCount,
    market,
    lookups,
    any_lookup: lookups.length > 0,
    reused,
    pages: details.map(d => ({ keyword: d.keyword, run_id: d.run_id, reused: d.reused, families: (d.families || []).length })),
    keywords_ok: k,
    failed,
    related_keywords: related.slice(0, 10),
    complement_ideas: complements.slice(0, 10),
  },
}];

// Turn each product-page lookup into one row of facts. Anything the page does not show is "not found", never 0.
// Lookups line up with Split Lookups by position; a failed lookup keeps the pick and says why.
const picks = $('Split Lookups').all().map(i => i.json);
const pages = $('Look Up Product (SerpApi)').all().map(i => i.json);
const NF = 'not found';

// Find the first value stored under `key` anywhere inside an object (offer layouts differ between products)
function findKey(obj, key, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 6) return undefined;
  if (key in obj) return obj[key];
  for (const v of Object.values(obj)) {
    const hit = findKey(v, key, depth + 1);
    if (hit !== undefined) return hit;
  }
  return undefined;
}
const text = v => (v === undefined || v === null || v === '' ? null : typeof v === 'object' ? (v.text ?? v.content ?? null) : String(v));
function errorText(res) {
  const e = res?.error;
  if (!e) return null;
  let msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const m = String(msg).match(/\\?"error\\?"\s*:\s*\\?"(.+?)\\?"/);
  return String(m ? m[1] : msg).replace(/\s+/g, ' ').trim().slice(0, 200);
}

return picks.map((p, idx) => {
  const page = pages[idx] || {};
  const base = {
    row_id: `i3|${p.run_id}|${p.asin}`, run_id: p.run_id, keyword: p.keyword, marketplace: p.marketplace,
    role: p.role, asin: p.asin, family_id: p.family_id, family_listings_on_page: p.family_size,
    title: p.title, brand_guess: p.brand_guess, price: p.price, rating: p.rating, reviews: p.reviews,
    units_family_on_page: p.units_family,
  };
  const err = errorText(page);
  const pr = page.product_results;
  if (err || !pr) {
    return { json: { ...base, lookup_status: 'failed', lookup_note: err || 'no product data returned', real_brand: NF, brand_guess_correct: 'unknown', sold_by: NF, ships_from: NF, fulfilled_by_amazon: NF, bsr_category: NF, bsr_all: NF, variations: NF, bought_last_month_page: NF, review_summary: NF, one_two_star_pct: NF, themes: [] } };
  }
  const pd = page.product_details || {};
  const spec = page.item_specifications || {};
  const realBrand = text(pd.brand_name) || text(spec.brand)
    || (pr.brand ? String(pr.brand).replace(/^Brand:\s*/i, '').replace(/^Visit the (.+) Store$/i, '$1').trim() : null);
  const soldBy = text(findKey(page.purchase_options, 'sold_by')) || text(findKey(page.product_results, 'sold_by'));
  const shipsFrom = text(findKey(page.purchase_options, 'ships_from')) || text(findKey(page.product_results, 'ships_from'));
  const bsr = (pd.best_sellers_rank || []).map(b => String(b.text || '').replace(/\s*\(See Top.*?\)\s*/i, '').trim()).filter(Boolean);
  const variants = (pr.variants || []).map(g => `${g.title}: ${(g.items || []).length}`);
  const insights = page.reviews_information?.summary?.insights || [];
  const themes = insights.map(t => ({
    theme: String(t.title || '').trim(),
    sentiment: t.sentiment || '',
    positive: t.mentions?.positive ?? null,
    negative: t.mentions?.negative ?? null,
    total: t.mentions?.total ?? null,
    summary: String(t.summary || '').trim(), // Amazon's own one-line summary of what customers say about this theme
  })).filter(t => t.theme && t.total !== null);
  // Star breakdown (% of ratings per star), when the page shows it
  const stars = page.reviews_information?.summary?.customer_reviews;
  const lowStarPct = stars && typeof stars === 'object' && ('1 star' in stars || '2 star' in stars)
    ? (Number(stars['1 star'] || 0) + Number(stars['2 star'] || 0)) : null;
  const brandKey = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return {
    json: {
      ...base,
      lookup_status: 'ok',
      lookup_note: themes.length ? '' : 'no review summary on this product page',
      real_brand: realBrand || NF,
      brand_guess_correct: realBrand && p.brand_guess ? (brandKey(realBrand).startsWith(brandKey(p.brand_guess)) || brandKey(p.brand_guess).startsWith(brandKey(realBrand)) ? 'yes' : 'no') : 'unknown',
      sold_by: soldBy || NF,
      ships_from: shipsFrom || NF,
      fulfilled_by_amazon: shipsFrom ? (/amazon/i.test(shipsFrom) ? 'yes' : 'no') : NF,
      bsr_category: bsr.length ? bsr[bsr.length - 1] : NF,
      bsr_all: bsr.length ? bsr.join(' | ') : NF,
      variations: variants.length ? variants.join(', ') : 'none listed',
      bought_last_month_page: pr.bought_last_month || NF,
      review_summary: page.reviews_information?.summary?.text || NF,
      one_two_star_pct: lowStarPct === null ? NF : lowStarPct,
      themes,
    },
  };
});

// One Products-tab row per inspected product; review themes written out as text
return $('Extract Products').all().map(i => {
  const { themes, ...p } = i.json;
  return {
    json: {
      ...p,
      review_themes: (themes || []).map(t => `${t.theme}: ${t.positive} positive / ${t.negative} negative of ${t.total} mentions${t.summary ? ` (Amazon: "${t.summary}")` : ''}`).join(' | ') || 'none',
    },
  };
});

// Judge each competitor as an ad target. Rules (published practice, m19's ASIN-targeting guide):
// target competitors priced ABOVE you, rated LOWER than you (or under 4.0 stars), with FEWER reviews than you,
// plus a heavy 1-2 star share when the product page shows it. Code writes every word; no AI.
const plan = $('Plan Run').first().json;
const rank = $('Rank Competitors').first().json;
const NF = 'not found';
const CUR = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' }[plan.marketplace] || '';
const money = v => (typeof v === 'number' ? `${CUR}${v.toFixed(2)}` : 'n/a');
const int = v => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : 'n/a');
const numOrNull = v => (v === '' || v === null || v === undefined || v === NF || !Number.isFinite(Number(v)) ? null : Number(v));

// Fresh lookups from this run (if any ran)
const fresh = {};
try {
  if ($('Extract Products').isExecuted) for (const i of $('Extract Products').all()) fresh[i.json.asin] = i.json;
} catch (e) { /* no lookups were needed */ }

// What we compare against: your product when entered, else the market median
const you = plan.you;
const m = rank.market;
const basis = {
  price: you.price ?? m.price,
  rating: you.rating,             // no "market" rating rule: under 4.0 stars is the fallback
  reviews: you.reviews,
  label: [you.price !== null ? 'your price' : `market median price (${m.based_on})`,
    you.rating !== null ? 'your rating' : 'the 4.0-star line',
    you.reviews !== null ? 'your review count' : 'the 1,000-review line'].join(', '),
};

const rows = rank.listed.map(c => {
  const f = fresh[c.competitor_asin];
  const r = rank.reused[c.competitor_asin];
  const facts = f || r || null;
  const source = f ? (f.lookup_status === 'ok' ? 'product page (looked up now)' : `lookup failed: ${f.lookup_note}`)
    : r ? `product page (reused, looked up within 24 h, ${r.asin})` : 'search page only';
  const ok = facts && facts.lookup_status === 'ok';
  const lowStar = ok ? numOrNull(facts.one_two_star_pct) : null;

  const checks = [];
  if (typeof c.price === 'number' && typeof basis.price === 'number' && c.price >= basis.price * 1.05)
    checks.push(`priced above ${you.price !== null ? 'you' : 'the market median'} (${money(c.price)} vs ${money(basis.price)})`);
  if (typeof c.rating === 'number') {
    // 0.1 star is display rounding, not a real gap: at least 0.2 lower counts
    if (you.rating !== null && c.rating <= you.rating - 0.2 + 1e-9) checks.push(`rated lower than you (${c.rating.toFixed(1)} vs ${you.rating.toFixed(1)} stars)`);
    else if (you.rating === null && c.rating < 4.0) checks.push(`rated under 4.0 (${c.rating.toFixed(1)} stars)`);
  }
  if (you.reviews !== null && c.reviews < you.reviews) checks.push(`fewer reviews than you (${int(c.reviews)} vs ${int(you.reviews)})`);
  else if (you.reviews === null && c.reviews < 1000) checks.push(`under 1,000 reviews (${int(c.reviews)})`);
  if (lowStar !== null && lowStar >= 15) checks.push(`${lowStar}% of ratings are 1-2 stars`);

  const n = checks.length;
  const priority = (c.relevance >= 50 && n >= 2) ? 'High'
    : ((c.relevance >= 50 && n === 1) || (c.relevance >= 30 && n >= 2)) ? 'Medium' : 'Low';
  const sales = c.has_sales ? `${int(c.units_floor)}+ bought last month (badge floor)` : 'no sales badge';
  const reason = `Ranks on ${c.coverage} keywords (best #${c.best_position}), ${sales}. `
    + (n ? `Weak spots: ${checks.join('; ')}.` : 'No weak spot found against ' + (you.price !== null || you.rating !== null || you.reviews !== null ? 'your product' : 'the market') + ': an ad here competes with a stronger offer.');

  return {
    rank: c.rank,
    ad_priority: priority,
    relevance: c.relevance,
    competitor_asin: c.competitor_asin,
    other_asins: c.asins.filter(a => a !== c.competitor_asin).join(', '),
    brand: ok && facts.real_brand && facts.real_brand !== NF ? facts.real_brand : (c.brand ?? 'unknown'),
    brand_source: ok && facts.real_brand && facts.real_brand !== NF ? 'product page' : 'guessed from title',
    title: c.title,
    keywords_ranked_on: c.keywords_ranked_on,
    coverage: c.coverage,
    best_position: c.best_position,
    units_floor: c.has_sales ? c.units_floor : NF,
    page_sales_share_pct: c.page_sales_share_pct,
    price: c.price,
    rating: c.rating ?? NF,
    reviews: c.reviews,
    newcomer: c.newcomer ? 'yes' : 'no',
    weak_spots: checks.join(' | ') || 'none',
    weak_spot_count: n,
    compared_with: basis.label,
    reason,
    relevance_breakdown: c.relevance_breakdown,
    bsr: ok ? facts.bsr_category : NF,
    sold_by: ok ? facts.sold_by : NF,
    ships_from: ok ? facts.ships_from : NF,
    one_two_star_pct: lowStar === null ? NF : lowStar,
    facts_source: source,
  };
});

return [{ json: { rows } }];

// One Targets-tab row per competitor (top 25), keyed by run so re-runs never overwrite older lists
const plan = $('Plan Run').first().json;
const run_id = `i3|${plan.marketplace}|${plan.batch_id}`;
return $('Judge Targets').first().json.rows.map(r => ({
  json: { row_id: `${run_id}|${r.rank}`, run_id, checked_at: plan.batch_id, marketplace: plan.marketplace, keywords: plan.keywords.join(' | '), ...r },
}));

// One Target Runs row: what was compared, what it cost, and the keyword ideas. Also the text shown on the form.
const plan = $('Plan Run').first().json;
const rank = $('Rank Competitors').first().json;
const rows = $('Judge Targets').first().json.rows;
const run_id = `i3|${plan.marketplace}|${plan.batch_id}`;
let freshLookups = 0, failedLookups = 0;
try {
  if ($('Extract Products').isExecuted) {
    const ex = $('Extract Products').all().map(i => i.json);
    freshLookups = ex.length;
    failedLookups = ex.filter(e => e.lookup_status !== 'ok').length;
  }
} catch (e) { /* no lookups */ }
const searched = plan.pages.filter(p => !p.reuse).length;
const count = p => rows.filter(r => r.ad_priority === p).length;
const CUR = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' }[plan.marketplace] || '';
const notes = [...plan.notes];
if (rank.failed.length) notes.push(`Not analyzed: ${rank.failed.join('; ')}`);
if (failedLookups) notes.push(`${failedLookups} product lookup(s) failed; those rows use search-page facts only`);
if (plan.you.price === null && plan.you.rating === null && plan.you.reviews === null) notes.push('No product entered: weak spots are measured against the market median price, the 4.0-star line and the 1,000-review line');
const row = {
  row_id: run_id, run_id, checked_at: plan.batch_id, tool: 'i3', marketplace: plan.marketplace,
  keywords: plan.keywords.join(' | '),
  pages: plan.pages.map(p => `${p.keyword}: ${p.reuse ? `reused (${p.age_hours} h old)` : 'new search'}`).join(' | '),
  searches_used: searched + freshLookups,
  page_searches: searched, product_lookups: freshLookups, lookups_reused: Object.keys(rank.reused).length,
  competitors_found: rank.competitors_found, own_excluded: rank.own_excluded, listed: rows.length,
  high: count('High'), medium: count('Medium'), low: count('Low'),
  your_price: plan.you.price ?? '', your_rating: plan.you.rating ?? '', your_reviews: plan.you.reviews ?? '',
  market_price_median: rank.market.price ?? '', market_rating_median: rank.market.rating ?? '', market_reviews_median: rank.market.reviews ?? '',
  related_keywords: rank.related_keywords.join(' | '), complement_ideas: rank.complement_ideas.join(' | '),
  notes: notes.join(' | '),
  cannot_tell: 'unit sales estimates (badge floors only) | ad costs or conversion | competitors outside page 1 | whether a competitor is out of stock',
};
const order = { High: 0, Medium: 1 };
const top = rows.filter(r => r.ad_priority !== 'Low').sort((a, b) => (order[a.ad_priority] - order[b.ad_priority]) || (a.rank - b.rank)).slice(0, 5);
const summary_text = [
  `${rows.length} competitors listed (${row.high} High, ${row.medium} Medium, ${row.low} Low) from ${plan.keywords.length} keywords on ${plan.marketplace}.`,
  `Searches used: ${row.searches_used} (${searched} page, ${freshLookups} product lookups; ${row.lookups_reused} lookups reused).`,
  ...(top.length ? ['Top targets:', ...top.map(r => `#${r.rank} ${r.ad_priority} · ${r.competitor_asin} · ${r.brand} · ${typeof r.price === 'number' ? CUR + r.price.toFixed(2) : 'n/a'} · ${r.coverage} keywords · ${r.weak_spots}`)] : ['No High or Medium targets: every listed competitor is at least as strong as the comparison point.']),
  ...(rank.complement_ideas.length ? [`Complement ideas (not scored): ${rank.complement_ideas.slice(0, 5).join(', ')}`] : []),
  ...(notes.length ? [`Notes: ${notes.join(' · ')}`] : []),
].join('\n');
return [{ json: { ...row, summary_text } }];

// The Target Runs row without the form-only summary text
const { summary_text, ...row } = $('Run Summary').first().json;
return [{ json: row }];

// Keyword rows for NEW searches only (score, stats, Amazon's related searches), so i5 and later reuse runs can read them.
// Reused pages already have their Keywords row from the tool that searched them.
const plan = $('Plan Run').first().json;
return $('Toolkit Core').first().json.keywords
  .filter(k => plan.to_search.includes(k.keyword))
  .map(json => ({ json }));

// ---- Result page: shared design (Amazon Toolkit). Presentation only: every value is copied from earlier nodes. ----
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const CURS = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const num = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v)) ? null : Number(v));
const int = v => (num(v) === null ? '–' : Math.round(num(v)).toLocaleString('en-US'));
const money = (v, cur) => (num(v) === null ? '–' : `${cur}${num(v).toFixed(2)}`);
const big = (v, cur = '') => { const n = num(v); if (n === null) return '–'; if (n >= 1e6) return `${cur}${(n / 1e6).toFixed(2)}M`; if (n >= 1e4) return `${cur}${Math.round(n / 1e3)}K`; return `${cur}${int(n)}`; };
const rating = v => (num(v) === null ? '–' : num(v).toFixed(1));
const spots = t => esc(String(t ?? '').split(' | ').join(' · '));
const split = t => String(t ?? '').split(' | ').map(s => s.trim()).filter(Boolean);
const LEVEL = { high: 'yes', medium: 'mid', low: 'no' };
const pill = (text, kind) => `<span class="pill ${kind || ''}">${esc(text)}</span>`;
const levelPill = t => pill(t, LEVEL[String(t || '').toLowerCase()] || 'muted');
const tiles = list => `<div class="tiles">${list.map(([v, l]) => `<div class="tile"><div class="tv">${v}</div><div class="tl">${esc(l)}</div></div>`).join('')}</div>`;
const section = (title, body) => (body ? `<section><h2>${esc(title)}</h2>${body}</section>` : '');
const table = (head, rows, right = []) => `<div class="tw"><table><thead><tr>${head.map((h, i) => `<th${right.includes(i) ? ' class="r"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td${right.includes(i) ? ' class="r"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const notesList = list => (list.length ? `<ul class="notes">${list.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : '');
const chips = list => (list.length ? `<div class="chips">${list.map(c => `<span class="chip">${esc(c)}</span>`).join('')}</div>` : '');

function page({ code, tool, colour, tint, title, meta, verdict, body, saved, cannotTell }) {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(tool)} · ${esc(title)}</title>
<style>
