}
// i3 Competitor Targeting: result page
const r = $('Run Summary').first().json;
const rows = $('Judge Targets').first().json.rows || [];
const cur = CURS[r.marketplace] || '';
const you = num(r.your_price) !== null || num(r.your_rating) !== null || num(r.your_reviews) !== null;
const vsLine = you ? `Against your product: ${money(r.your_price, cur)} · ${esc(r.your_rating || '–')}★ · ${int(r.your_reviews)} reviews`
  : `No product entered: measured against the market median ${money(r.market_price_median, cur)}, the 4.0★ line and the 1,000-review line`;
const ORDER = { High: 0, Medium: 1, Low: 2 };
const best = rows.filter(x => x.ad_priority !== 'Low').sort((a, b) => ORDER[a.ad_priority] - ORDER[b.ad_priority] || a.rank - b.rank).slice(0, 8);
const who = x => `<b>${esc(x.brand || 'unknown')}</b><div class="sub">${esc(x.competitor_asin)} · ${esc(x.coverage)} keywords · best #${esc(x.best_position)}</div>`;
const pr = p => `<span class="pill ${p === 'High' ? 'yes' : p === 'Medium' ? 'mid' : 'muted'}">${esc(p)}</span>`;
const tgt = x => [pr(x.ad_priority), who(x), `<b>${esc(x.relevance)}</b>`, money(x.price, cur), rating(x.rating), int(x.reviews), spots(x.weak_spots)];
const html = page({
  code: 'i3', tool: 'Competitor Targeting', colour: '#8B4E34', tint: '#f8f1ec',
  title: split(r.keywords).join(' · '), meta: [r.marketplace, r.checked_at, `${r.searches_used} search${r.searches_used == 1 ? '' : 'es'} (${r.page_searches} page${r.page_searches == 1 ? '' : 's'}, ${r.product_lookups} lookup${r.product_lookups == 1 ? '' : 's'}, ${r.lookups_reused} reused)`],
  verdict: `<div class="big">${esc(r.high)} High · ${esc(r.medium)} Medium · ${esc(r.low)} Low</div><p>${vsLine}</p>`,
  body: [
    tiles([[int(r.competitors_found), 'competitors on page 1'], [int(r.listed), 'ranked and judged'], [int(r.own_excluded), 'yours, left out'], [esc(r.searches_used), 'searches used']]),
    section('Best targets', best.length ? table(['Priority', 'Competitor', 'Relevance', 'Price', 'Rating', 'Reviews', 'Weak spots'], best.map(tgt), [2, 3, 4, 5]) : '<p>No High or Medium targets: no competitor has a weak spot against you.</p>'),
    section('Most relevant', table(['Priority', 'Competitor', 'Relevance', 'Price', 'Rating', 'Reviews', 'Weak spots'], [...rows].sort((a, b) => a.rank - b.rank).slice(0, 5).map(tgt), [2, 3, 4, 5])),
    section('Pages', chips(split(r.pages))),
    section('Related keywords', chips(split(r.related_keywords).slice(0, 10))),
    section('Complement ideas (not scored)', chips(split(r.complement_ideas).slice(0, 6))),
    section('Notes', notesList(split(r.notes))),
  ].join(''),
  saved: 'Targets, Target Runs, Products, Listings, Keywords',
  cannotTell: split(r.cannot_tell),
});
return [{ json: { html } }];
